/**
 * Sync Write|Edit Dispatcher — PreToolUse Write|Edit Hook
 * Consolidates 5 Write|Edit PreToolUse hooks into a single dispatcher.
 *
 * Consolidated hooks (security-first order):
 * - content-secret-scanner (scans for secrets in file content — FIRST)
 * - file-guard (protects critical files from modification — SECOND)
 * - dependency-confusion-scanner (warns on unclaimed package refs — advisory)
 * - write-headers (adds headers to new files — input modifier)
 * - unified-quality-dispatcher (quality checks — LAST)
 *
 * SHORT-CIRCUIT: On first block, returns immediately without running remaining hooks.
 * Merges additionalContext from all passing hooks into a single output.
 *
 * CC 2.1.9 Compliant: Single PreToolUse dispatcher with merged additionalContext
 */

import type { HookInput, HookResult , HookContext} from '../../types.js';
import { outputSilentSuccess, outputWithUpdatedInput, logHook, extractContext } from '../../lib/common.js';

// Import consolidated hook implementations
import { contentSecretScanner } from './content-secret-scanner.js';
import { fileGuard } from './file-guard.js';
import { contextFileBudgetGuard } from './context-file-budget-guard.js';
import { dependencyConfusionScanner } from './dependency-confusion-scanner.js';
import { writeHeaders } from '../input-mod/write-headers.js';
import { unifiedWriteEditQualityDispatcher } from './unified-quality-dispatcher.js';
import { NOOP_CTX } from '../../lib/context.js';

const HOOK_NAME = 'sync-write-edit-dispatcher';

interface WriteEditHookConfig {
  name: string;
  fn: (input: HookInput, ctx: HookContext) => HookResult;
}

/**
 * Registry of Write|Edit PreToolUse hooks, executed in security-first order.
 * Blockers/scanners run first; quality advisory runs last.
 */
const WRITE_EDIT_HOOKS: WriteEditHookConfig[] = [
  { name: 'content-secret-scanner', fn: contentSecretScanner },
  { name: 'file-guard', fn: fileGuard },
  { name: 'context-file-budget-guard', fn: contextFileBudgetGuard },
  { name: 'dependency-confusion-scanner', fn: dependencyConfusionScanner },
  { name: 'write-headers', fn: writeHeaders },
  { name: 'unified-quality-dispatcher', fn: unifiedWriteEditQualityDispatcher },
];

/**
 * Build the merged HookResult from collected context parts and optional updatedInput.
 */
type Decision = { decision: 'deny' | 'ask'; reason: string; from: string };

const DECISION_RANK: Record<Decision['decision'], number> = { deny: 2, ask: 1 };

/**
 * Attach the most severe sibling verdict to a merged envelope. Found by the
 * verdict-probe suite (tests/hooks/verdict-probes): file-guard and
 * context-file-budget-guard both answer `ask` (continue:true +
 * permissionDecision), which is neither a block (short-circuited above) nor
 * context, so the merge below dropped it on the floor and both guards had
 * been inert in production since they moved from deny to ask (#2947). The
 * bash and task dispatchers short-circuit on ask; this one keeps collecting
 * so write-headers' updatedInput still lands, and carries the verdict along.
 */
function withDecision(result: HookResult, decision: Decision | undefined): HookResult {
  if (!decision) return result;
  return {
    ...result,
    hookSpecificOutput: {
      ...(result.hookSpecificOutput ?? {}),
      hookEventName: 'PreToolUse',
      permissionDecision: decision.decision,
      permissionDecisionReason: decision.reason,
    },
  };
}

function buildMergedResult(
  contextParts: string[],
  updatedInput: Record<string, unknown> | undefined,
  decision?: Decision,
): HookResult {
  const mergedContext = contextParts.length > 0 ? contextParts.join('\n\n---\n\n') : null;

  if (decision) {
    logHook(HOOK_NAME, `${decision.from} answered ${decision.decision}; carried through the merge`);
  }

  if (updatedInput && mergedContext) {
    logHook(HOOK_NAME, `Merged ${contextParts.length} context(s) + updatedInput`);
    return withDecision({
      continue: true,
      suppressOutput: true,
      hookSpecificOutput: { hookEventName: 'PreToolUse', updatedInput, additionalContext: mergedContext },
    }, decision);
  }

  if (updatedInput) {
    logHook(HOOK_NAME, 'updatedInput only — no context');
    return withDecision(outputWithUpdatedInput(updatedInput), decision);
  }

  if (mergedContext) {
    logHook(HOOK_NAME, `Merged ${contextParts.length} context(s)`);
    return withDecision({
      continue: true,
      suppressOutput: true,
      hookSpecificOutput: { additionalContext: mergedContext, hookEventName: 'PreToolUse' },
    }, decision);
  }

  if (decision) return withDecision({ continue: true, suppressOutput: true }, decision);

  logHook(HOOK_NAME, 'All hooks silent');
  return outputSilentSuccess();
}

/**
 * Consolidated sync Write|Edit PreToolUse dispatcher.
 *
 * Execution order:
 * 1. content-secret-scanner (can block — security critical)
 * 2. file-guard (can block — security critical)
 * 3. dependency-confusion-scanner (warn-only — supply-chain advisory)
 * 4. write-headers (input modifier — adds headers to new files)
 * 5. unified-quality-dispatcher (context producer)
 *
 * On first block: SHORT-CIRCUIT immediately.
 * On pass: merge additionalContext and updatedInput from all hooks.
 */
export function syncWriteEditDispatcher(input: HookInput, ctx: HookContext = NOOP_CTX): HookResult {
  const contextParts: string[] = [];
  let updatedInput: Record<string, unknown> | undefined;
  let decision: Decision | undefined;

  for (const hook of WRITE_EDIT_HOOKS) {
    try {
      const result = hook.fn(input, ctx);

      if (!result.continue) {
        ctx.log(HOOK_NAME, `${hook.name} blocked — short-circuiting`);
        return result;
      }

      const pd = (result.hookSpecificOutput as { permissionDecision?: string; permissionDecisionReason?: string } | undefined)?.permissionDecision;
      if (pd === 'deny' || pd === 'ask') {
        const candidate: Decision = { decision: pd, reason: String(result.hookSpecificOutput?.permissionDecisionReason ?? ''), from: hook.name };
        if (!decision || DECISION_RANK[candidate.decision] > DECISION_RANK[decision.decision]) decision = candidate;
        ctx.log(HOOK_NAME, `${hook.name}: ${pd} collected`);
      }

      if (result.hookSpecificOutput?.updatedInput) {
        updatedInput = result.hookSpecificOutput.updatedInput as Record<string, unknown>;
        ctx.log(HOOK_NAME, `${hook.name}: updatedInput collected`);
      }

      const context = extractContext(result);
      if (context) {
        contextParts.push(context);
        ctx.log(HOOK_NAME, `${hook.name}: additionalContext collected`);
      }
    } catch (error) {
      const msg = error instanceof Error ? error.message : String(error);
      ctx.log(HOOK_NAME, `${hook.name} failed: ${msg}`, 'warn');
    }
  }

  return buildMergedResult(contextParts, updatedInput, decision);
}
